import csv
for fn in ['ae_death_age_gender.csv','ae_ip_termination_by_month.csv','ae_ip_termination.csv']:
    print('='*25, fn)
    try:
        with open(fn) as f:
            rows = list(csv.reader(f))
        print('header:', rows[0])
        print('nrows:', len(rows)-1)
        for r in rows[1:6]:
            print(r)
    except Exception as e:
        print('ERR', e)
